package org.eclipse.rdf4j.common.iteration;

/**
 * Test-only bridge to {@link TimeLimitIteration#interrupt()}, the time limit's own expiry entry point. Lets an LMDB
 * test elapse a one-hour limit at a chosen point inside the evaluation instead of racing a short wall-clock deadline.
 */
public final class LmdbTimeLimitTestAccess {

	private LmdbTimeLimitTestAccess() {
	}

	/** Expires the time limit now: cooperative cancellation first, then the configured interrupt escalation. */
	public static void expire(TimeLimitIteration<?> limit) {
		limit.interrupt();
	}
}
